(
  (t.class_id IS NULL AND EXISTS (
    SELECT 1 FROM teacher_students ts WHERE ts.teacher_id=t.teacher_id AND ts.student_id=t.student_id AND ts.status='active'
  ))
  OR EXISTS (
    SELECT 1 FROM teaching_class_members m JOIN teaching_classes c ON c.id=m.class_id
    WHERE c.teacher_id=t.teacher_id AND m.student_id=t.student_id AND (t.class_id IS NULL OR m.class_id=t.class_id)
  )
)
